preConditionHook:
// Huge bar, opposite inside bar, resumption (Brian's notes ON-24, TRIAGE #24,
// p. 26). As written the SHORT: a huge bear bar bb bars ago (ON-12-a shape at
// hugeAtr, nearFraction for open and close) whose low took out the prior
// breakLookback-bar low, no high since above its high, later a bullish strict
// inside bar (open near low, close near high), and this the first red bar after
// it. LONG mirrors. bb scans 2..maxBars, any anchor fires; the most recent
// qualifying inside bar is used (index sentinel 0, bar indices are not prices).
// Not InsideBar (single strict inside test, no chain).
// The large shaped bar is the shared primitive ON-12-a (LargeShapedBarAtLag),
// inlined in one form: range strictly between minRangeAtr and maxRangeAtr x the
// ATR AS OF THAT BAR (atrValue[lag]), open in the bottom openFraction, close in
// the top closeFraction (bear: open top, close bottom). During warm-up the
// lagged ATR reads 0, so `r < maxRangeAtr * 0` fails and nothing fires -- as in EL.
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, SwingLowRejection's
// block verbatim -- seeded with a full N-term sum on the first calculated bar or
// when the length changes, and after that TWO statements (S += in; S -= out;) --
// EL evaluates S[1] + in - out left to right. It stays in the hook, which the
// generator emits unconditionally.
if (atrLenState != (int)atrLength) {
    atrSum = 0.0;
    for (aa = 0; aa < (int)atrLength; ++aa) {
        hiV = high[aa] > close[aa + 1] ? high[aa] : close[aa + 1];
        loV = low[aa] < close[aa + 1] ? low[aa] : close[aa + 1];
        atrSum += hiV - loV;
    }
    atrLenState = (int)atrLength;
} else {
    outIdx = (int)atrLength;
    hiV = high[0] > close[1] ? high[0] : close[1];
    loV = low[0] < close[1] ? low[0] : close[1];
    hiO = high[outIdx] > close[outIdx + 1] ? high[outIdx] : close[outIdx + 1];
    loO = low[outIdx] < close[outIdx + 1] ? low[outIdx] : close[outIdx + 1];
    atrSum += hiV - loV;
    atrSum -= hiO - loO;
}
atrValue = atrSum / (int)atrLength;
// EL reads atrValue[k], the VARIABLE's own history: 0 for every bar before the
// strategy's first evaluated one, the stored value after. Mirrored as a growing
// history (StochasticCross's push_back form), so atrHist[size-1-k] is atrValue[k]
// and k past the start reads 0 -- and an input change mid-run never discards it,
// as a resized ring buffer would.
atrHist.push_back(atrValue);
fireLong = false;
fireShort = false;
for (bb = 2; bb <= (int)maxBars; ++bb) {
    bigR = high[bb] - low[bb];
    atrIdx = (int)atrHist.size() - 1 - (bb);
    bigA = atrIdx >= 0 ? atrHist[(std::size_t)atrIdx] : 0.0;
    sizeOk = el_gt(bigR, hugeAtr * bigA) && el_lt(bigR, maxRangeAtr * bigA);
    bullBig = sizeOk && el_le(open[bb] - low[bb], nearFraction * bigR) && el_le(high[bb] - close[bb], nearFraction * bigR);
    bearBig = sizeOk && el_le(high[bb] - open[bb], nearFraction * bigR) && el_le(close[bb] - low[bb], nearFraction * bigR);
    winHi = high[bb + 1];
    winLo = low[bb + 1];
    for (jj = bb + 2; jj <= bb + (int)breakLookback; ++jj) {
        if (el_gt(high[jj], winHi)) winHi = high[jj];
        if (el_lt(low[jj], winLo)) winLo = low[jj];
    }
    holdLo = true;
    holdHi = true;
    for (jj = 0; jj <= bb - 1; ++jj) {
        if (el_lt(low[jj], low[bb])) holdLo = false;
        if (el_gt(high[jj], high[bb])) holdHi = false;
    }
    insBear = 0;
    insBull = 0;
    for (jj = 1; jj <= bb - 1; ++jj) {
        jr = high[jj] - low[jj];
        if (insBear == 0 && el_lt(high[jj], high[jj + 1]) && el_gt(low[jj], low[jj + 1]) && el_lt(close[jj], open[jj]) && el_le(high[jj] - open[jj], nearFraction * jr) && el_le(close[jj] - low[jj], nearFraction * jr)) insBear = jj;
        if (insBull == 0 && el_lt(high[jj], high[jj + 1]) && el_gt(low[jj], low[jj + 1]) && el_gt(close[jj], open[jj]) && el_le(open[jj] - low[jj], nearFraction * jr) && el_le(high[jj] - close[jj], nearFraction * jr)) insBull = jj;
    }
    if (insBear > 0) {
        noGreen = true;
        for (jj = 1; jj <= insBear - 1; ++jj) {
            if (el_gt(close[jj], open[jj])) noGreen = false;
        }
        if (bullBig && el_gt(high[bb], winHi) && holdLo && noGreen && el_gt(close[0], open[0])) fireLong = true;
    }
    if (insBull > 0) {
        noRed = true;
        for (jj = 1; jj <= insBull - 1; ++jj) {
            if (el_lt(close[jj], open[jj])) noRed = false;
        }
        if (bearBig && el_lt(low[bb], winLo) && holdHi && noRed && el_lt(close[0], open[0])) fireShort = true;
    }
}
